function pa_emp(array $d,int $id): array {$e=workforce_employee_by_id($d,$id);return $e?:['id'=>$id,'code'=>'EMP'.$id,'name'=>'Unknown','position'=>'other','profile'=>[],'payroll'=>[]];}
function pa_branch(array $d,int $id): array {$b=workforce_branch($d,$id);return $b?:['code'=>'-','name'=>'ไม่ระบุสาขา'];}
function pa_dt(?string $v): ?DateTime {if(!$v)return null;try{return new DateTime($v);}catch(Throwable $e){return null;}}
function pa_money($v): float {return max(0,(float)$v);}function pa_minutes_between(?string $in,?string $out): int {$a=pa_dt($in);$b=pa_dt($out);if(!$a||!$b)return 0;$s=$b->getTimestamp()-$a->getTimestamp();return $s>0?(int)floor($s/60):0;}function pa_hm(int $m): string {$m=max(0,$m);return sprintf('%d:%02d',(int)floor($m/60),$m%60);}function pa_range(): array {$t=new DateTime('today');return [$t->format('Y-m-01'),$t->format('Y-m-t')];}function pa_evidence_url(int $id,string $type): string {return 'attendance-evidence.php?id='.$id.'&type='.$type;}function pa_late(string $in,string $start,int $grace): int {$a=pa_dt($in);if(!$a)return 0;$b=new DateTime($a->format('Y-m-d').' '.$start);return max(0,(int)floor(($a->getTimestamp()-$b->getTimestamp())/60)-$grace);}
$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save_payroll'){if(!$canManage){http_response_code(403);exit('Permission denied');}csrf_check();try{$eid=(int)($_POST['employee_id']??0);$type=(string)($_POST['payroll_type']??'daily');if(!in_array($type,['daily','hourly','monthly'],true))$type='daily';$daily=pa_money($_POST['daily_rate']??0);$hourly=pa_money($_POST['hourly_rate']??0);$monthly=pa_money($_POST['monthly_salary']??0);$ot=pa_money($_POST['overtime_rate']??0);$start=(string)($_POST['start_time']??'18:00');if(!preg_match('/^\d{2}:\d{2}$/',$start))$start='18:00';$std=max(1,min(24,(float)($_POST['standard_hours']??8)));db_mutate(function($x)use($session,$eid,$type,$daily,$hourly,$monthly,$ot,$start,$std){foreach($x['employees'] as &$e)if((int)$e['id']===$eid){$e['payroll']=['type'=>$type,'daily_rate'=>(string)$daily,'hourly_rate'=>(string)$hourly,'monthly_salary'=>(string)$monthly,'overtime_rate'=>(string)$ot,'start_time'=>$start,'standard_hours'=>(string)$std];$e['updated_at']=date('c');workforce_sync_employee_to_pr($x,$e);audit_permission($x,$session,'employee_payroll_updated',['employee_id'=>$eid]);return $x;}unset($e);throw new RuntimeException('ไม่พบ Employee');});$msg='บันทึก Payroll แล้ว';$d=db_load();}catch(Throwable $e){$err=$e->getMessage();}}
list($defFrom,$defTo)=pa_range();$from=(string)($_GET['from']??$defFrom);$to=(string)($_GET['to']??$defTo);$employeeFilter=(int)($_GET['employee_id']??0);$branchFilter=(int)($_GET['branch_id']??0);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=$defFrom;if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=$defTo;if($from>$to){$tmp=$from;$from=$to;$to=$tmp;}$grace=(int)($d['settings']['attendance_late_grace_minutes']??15);
$filtered=[];foreach($d['attendance']??[] as $a){$in=(string)($a['check_in']??'');if($in==='')continue;$date=substr($in,0,10);if($date<$from||$date>$to)continue;$eid=(int)($a['employee_id']??0);if(!$eid)$eid=(int)(workforce_employee_by_pr($d,(int)($a['pr_id']??0))['id']??0);if($employeeFilter&&$eid!==$employeeFilter)continue;if($branchFilter&&(int)($a['branch_id']??0)!==$branchFilter)continue;$a['_employee_id']=$eid;$filtered[]=$a;}usort($filtered,function($a,$b){return strcmp((string)($b['check_in']??''),(string)($a['check_in']??''));});
$summary=[];$detail=[];foreach($filtered as $a){$eid=(int)$a['_employee_id'];$emp=pa_emp($d,$eid);$pay=$emp['payroll']??[];$std=max(1,(float)($pay['standard_hours']??8));$stdMin=(int)round($std*60);$isFinal=workforce_payroll_final($a);$worked=$isFinal?pa_minutes_between((string)$a['check_in'],(string)($a['check_out']??'')):0;$ot=max(0,$worked-$stdMin);$start=(string)($pay['start_time']??($d['settings']['shop_open_time']??'18:00'));$late=pa_late((string)$a['check_in'],$start,$grace);$type=(string)($pay['type']??'daily');$variable=0.0;$regular=max(0,$worked-$ot);$otRate=pa_money($pay['overtime_rate']??0);if($isFinal){if($type==='hourly')$variable=($regular/60)*pa_money($pay['hourly_rate']??0)+($ot/60)*$otRate;elseif($type==='daily')$variable=pa_money($pay['daily_rate']??0)+($ot/60)*$otRate;else $variable=($ot/60)*$otRate;}if(!isset($summary[$eid]))$summary[$eid]=['employee'=>$emp,'days'=>0,'minutes'=>0,'ot'=>0,'late_count'=>0,'late_minutes'=>0,'missing_out'=>0,'pending_review'=>0,'pay_variable'=>0.0];$summary[$eid]['days']+=($isFinal?1:0);$summary[$eid]['minutes']+=$worked;$summary[$eid]['ot']+=$ot;$summary[$eid]['late_count']+=($late>0?1:0);$summary[$eid]['late_minutes']+=$late;$summary[$eid]['missing_out']+=in_array(workforce_attendance_state($a),['missing_checkout','provisional'],true)?1:0;$summary[$eid]['pending_review']+=($isFinal?0:1);$summary[$eid]['pay_variable']+=$variable;$detail[]=['a'=>$a,'employee'=>$emp,'worked'=>$worked,'ot'=>$ot,'late'=>$late,'pay'=>$variable,'final'=>$isFinal,'state'=>workforce_attendance_state($a)];}
foreach($summary as &$s){$pay=$s['employee']['payroll']??[];if(($pay['type']??'daily')==='monthly'){$sd=new DateTime($from);$ed=new DateTime($to);$daysSel=(int)$sd->diff($ed)->days+1;$dim=(int)$sd->format('t');$ratio=$sd->format('Y-m')===$ed->format('Y-m')?min(1,$daysSel/$dim):1;$s['estimate']=pa_money($pay['monthly_salary']??0)*$ratio+$s['pay_variable'];}else $s['estimate']=$s['pay_variable'];}unset($s);
if(($_GET['export']??'')==='csv'){if(!$canExport){http_response_code(403);exit('Permission denied');}header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="mrbar-workforce-payroll-'.$from.'-to-'.$to.'.csv"');echo "\xEF\xBB\xBF";$fp=fopen('php://output','w');fputcsv($fp,['Employee Code','ชื่อ','ตำแหน่ง','วันที่','สาขา','Check-In','Check-Out','ชั่วโมงทำงาน','OT','สาย(นาที)','GPS IN(m)','GPS OUT(m)','Status','ประมาณการค่าจ้าง']);foreach($detail as $r){$a=$r['a'];$b=pa_branch($d,(int)($a['branch_id']??0));$e=$r['employee'];fputcsv($fp,[(string)$e['code'],(string)$e['name'],workforce_position_label((string)$e['position']),substr((string)$a['check_in'],0,10),(string)$b['name'],date('H:i:s',strtotime((string)$a['check_in'])),empty($a['check_out'])?'':date('H:i:s',strtotime((string)$a['check_out'])),number_format($r['worked']/60,2),number_format($r['ot']/60,2),$r['late'],isset($a['checkin_distance_m'])?round((float)$a['checkin_distance_m']):'',isset($a['checkout_distance_m'])?round((float)$a['checkout_distance_m']):'',($r['final']?'FINAL':'PENDING_REVIEW'),number_format($r['pay'],2)]);}fclose($fp);exit;}
